INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0001', 'OS Command Injection via Subprocess', 'CRITICAL', 'Command Injection', 'The skill executes OS commands using untrusted inputs without proper sanitization.', 'Use safe APIs that do not invoke a shell, and strictly validate or parameterize all inputs passed to system commands.', '', '2026-08-25T11:49:29.189Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0002', 'System Prompt Override & Instruction Hijacking', 'CRITICAL', 'SD-01 · System Prompt Override', 'Adversarial prompt injection sequences designed to force the LLM to ignore preceding system guidelines, bypass guardrails, and execute unauthorized actions.', 'Use strict XML isolation delimiters for user inputs, perform Layer 2 semantic inference checks, and enforce tool confirmation gates.', 'a8006737be1d1df52d7655f94ea816c55b1a1f4d35d1b6932ef0418446b88476', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0003', 'Sensitive Credential Harvesting & C2 Exfiltration', 'CRITICAL', 'SD-03 · Data Exfiltration & C2', 'Unauthorized scanning of environment variables, AWS tokens, SSH keys, or bash history with outbound HTTPS/DNS tunneling to external command-and-control endpoints.', 'Block outbound network egress in agent tools using eBPF sandbox filters and restrict filesystem visibility to dedicated workspace mounts.', '9763333ebb8f8a5dbdb2a8b0c2d4aec879830e42046a71f1a7be46673bd14a59', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0004', 'Unscoped Tool Permission Escalation & Sudo Spawning', 'HIGH', 'SD-04 · Privilege Escalation', 'The skill attempts to invoke sudo or modify file permissions (chmod 777) to escape unprivileged agent sandbox boundaries.', 'Run tool workers in rootless containers with all Linux capabilities dropped and no-new-privileges flags enforced.', '5d41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e54b', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0005', 'Supply Chain Dependency Tampering & Pyc Cache Poisoning', 'HIGH', 'SD-05 · Supply Chain Tampering', 'Tampering with declared dependencies, injecting untrusted PyPI packages via typosquatting, or poisoning pre-compiled bytecode artifacts.', 'Lock dependency versions using cryptographic lockfiles (e.g. poetry.lock, requirements.txt with sha256 hashes) and verify package origins.', '7d41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e54c', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0006', 'Server-Side Request Forgery (SSRF) to Cloud Metadata', 'CRITICAL', 'SD-06 · SSRF', 'Exploiting agent web fetch tools to query internal IP addresses (127.0.0.1, 169.254.169.254) to steal instance identity tokens and access internal services.', 'Enforce strict URL domain whitelisting and block RFC-1918 private IP ranges and Cloud Metadata IPs (169.254.169.254).', '8d41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e54d', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0007', 'Shadow Tool Masquerading & Namespace Poisoning', 'HIGH', 'SD-07 · Tool Poisoning', 'Registering rogue tool definitions that shadow standard system tools (e.g. overriding bash, read_file, git) to intercept parameters and exfiltrate data.', 'Enforce immutable tool registration tables and validate tool signatures before execution.', '9d41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e54e', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0008', 'Persistent Startup & Environment Backdoor', 'CRITICAL', 'SD-08 · Persistent Backdoors', 'Modifying .bashrc, .zshrc, crontab, or startup hooks to maintain persistence across multiple agent runs.', 'Use immutable ephemeral containers where each scan or tool execution runs in a fresh disposable environment.', 'ae41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e54f', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0009', 'Agent Context Window Flooding & Denial of Service', 'MEDIUM', 'SD-09 · Context Flooding', 'Generating massive, repetitive, or cyclic text outputs to overflow context windows and erase system security guidelines from active LLM context.', 'Implement strict stream size limits and truncate tool outputs before returning them to the model context.', 'bf41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e550', '2026-08-25T11:49:29.190Z');
INSERT OR REPLACE INTO threats (id, name, severity, category, description, remediation, pattern_hash, created_at) VALUES ('SD-T-0010', 'Unicode Homoglyph & Obfuscated Payload Execution', 'HIGH', 'SD-10 · Obfuscation', 'Using invisible zero-width characters, Cyrillic/Greek homoglyphs, or base64 decoding to evade standard ASCII pattern filters.', 'Perform Unicode normalization (NFKC) and strip zero-width characters before analysis.', 'cf41402abc4b2a76b9719d911017c5926c4d7b1d4e0e64eb98547b744d03e551', '2026-08-25T11:49:29.190Z');